import XCTest

@testable import ArrowGeneratorCore

class DependencyFileTests: XCTestCase {
  func testValidOutput() throws {
    let expectedOutput = """
      // Generated by arrow. Do not edit.

      import Arrow

      enum AppDependencies: DependencyRegistry {
        static func register(in container: Container) {
          let module = Module()

          container.register(Type.self, objectScope: .transient) { resolver in
            module.provide(
              resolver.resolve(B.self),
              a: resolver.resolve(A.self),
              c: resolver.resolve(C.self, name: "cType")
            )
          }
        }
      }
      """

    var file = ""
    DependencyFile(presenter: DependencyFilePresenterMock(.fixture())).file.write(to: &file)
    XCTAssertEqual(expectedOutput, file)
  }

  func testValidOutput_publicRegistry() throws {
    let expectedOutput = """
      // Generated by arrow. Do not edit.

      import Arrow

      public enum AnalyticsDependencies: DependencyRegistry {
        public static func register(in container: Container) {
          let module = Module()

          container.register(Type.self, objectScope: .lazySingleton) { resolver in
            module.provide
          }
        }
      }
      """

    var file = ""
    let uiModel = FileUiModel.fixture(
      registry: .init(name: "AnalyticsDependencies", isPublic: true),
      dependencies: [.fixture(isFunc: false, scope: "lazySingleton", parameters: [])])
    DependencyFile(presenter: DependencyFilePresenterMock(uiModel)).file.write(to: &file)
    XCTAssertEqual(expectedOutput, file)
  }

  func testValidOutput_moreModules() throws {
    let expectedOutput = """
      // Generated by arrow. Do not edit.

      import Arrow

      enum AppDependencies: DependencyRegistry {
        static func register(in container: Container) {
          let module = Module()
          let extraModule = ExtraModule()

          container.register(Type.self, objectScope: .transient) { resolver in
            module.provide(
              resolver.resolve(B.self),
              a: resolver.resolve(A.self),
              c: resolver.resolve(C.self, name: "cType")
            )
          }

          container.register(ExtraType.self, name: "ExtraTypeName", objectScope: .singleton) { resolver in
            extraModule.provide(
              resolver.resolve(Z.self),
              q: resolver.resolve(Q.self, name: "qType"),
              e: resolver.resolve(E.self)
            )
          }

          container.register(VariableType.self, name: "VariableTypeName", objectScope: .singleton) { resolver in
            extraModule.provideVariable
          }

          container.register(MoreType.self, objectScope: .singleton) { resolver in
            extraModule.provideMoreType()
          }

          container.register(Type2.self, name: "MoreType2", objectScope: .singleton) { resolver in
            extraModule.provideTypeTwo(
              resolver.resolve(A.self)
            )
          }
        }
      }
      """

    var file = ""
    let dependencies: [DependencyUiModel] = [
      .fixture(),
      .fixture(
        module: "ExtraModule",
        type: "ExtraType",
        name: "ExtraTypeName",
        block: "provide",
        scope: "singleton",
        parameters: [
          .init(type: "Z", label: nil, id: nil, isLast: false),
          .init(type: "Q", label: "q", id: "qType", isLast: false),
          .init(type: "E", label: "e", id: nil, isLast: true),
        ]),
      .fixture(
        module: "ExtraModule",
        isFunc: false,
        type: "VariableType",
        name: "VariableTypeName",
        block: "provideVariable",
        scope: "singleton"),
      .fixture(
        module: "ExtraModule",
        type: "MoreType",
        block: "provideMoreType",
        scope: "singleton",
        parameters: []),
      .fixture(
        module: "ExtraModule",
        type: "Type2",
        name: "MoreType2",
        block: "provideTypeTwo",
        scope: "singleton",
        parameters: [
          .init(type: "A", label: nil, id: nil, isLast: true)
        ]),
    ]
    DependencyFile(presenter: DependencyFilePresenterMock(.fixture(dependencies: dependencies)))
      .file
      .write(to: &file)
    XCTAssertEqual(expectedOutput, file)
  }
}

extension DependencyFileTests {
  func testVariableName() {
    XCTAssertEqual(DependencyFile.variableName(for: "MoreModule"), "moreModule")
    XCTAssertEqual(DependencyFile.variableName(for: "URLModule"), "urlModule")
    XCTAssertEqual(DependencyFile.variableName(for: "API"), "api")
    XCTAssertEqual(DependencyFile.variableName(for: "Foo.Bar"), "foo_Bar")
    XCTAssertEqual(DependencyFile.variableName(for: "module"), "module")
  }

  func testModuleVariables_escapeKeywordsAndAvoidCollisions() {
    let dependencies: [DependencyUiModel] = ["Default", "Foo.Bar", "Foo_Bar"].map {
      .fixture(module: $0, isFunc: false, block: "provide", parameters: [])
    }

    var file = ""
    DependencyFile(presenter: DependencyFilePresenterMock(.fixture(dependencies: dependencies)))
      .file
      .write(to: &file)

    XCTAssertTrue(file.contains("let `default` = Default()"))
    XCTAssertTrue(file.contains("`default`.provide"))
    XCTAssertTrue(file.contains("let foo_Bar = Foo.Bar()"))
    XCTAssertTrue(file.contains("let foo_Bar2 = Foo_Bar()"))
    XCTAssertTrue(file.contains("foo_Bar2.provide"))
  }

  func testRegistryDefaultName() {
    XCTAssertEqual(RegistryConfiguration.defaultName(for: "Analytics"), "AnalyticsDependencies")
    XCTAssertEqual(RegistryConfiguration.defaultName(for: "my-pkg"), "MyPkgDependencies")
    XCTAssertEqual(RegistryConfiguration.defaultName(for: "core_utils"), "CoreUtilsDependencies")
    XCTAssertEqual(RegistryConfiguration.defaultName(for: "2D"), "_2DDependencies")
    XCTAssertEqual(RegistryConfiguration.defaultName(for: ""), "AppDependencies")
  }
}

struct DependencyFilePresenterMock: DependencyFilePresenting {
  let fileUiModel: FileUiModel

  init(_ uiModel: FileUiModel) {
    self.fileUiModel = uiModel
  }
}

extension FileUiModel {
  static func fixture(
    registry: RegistryConfiguration = .init(name: "AppDependencies", isPublic: false),
    imports: [String] = ["Arrow"],
    dependencies: [DependencyUiModel] = [.fixture()]
  ) -> Self {
    .init(registry: registry, imports: imports, dependencies: dependencies)
  }
}

extension DependencyUiModel {
  static func fixture(
    module: String = "Module",
    isFunc: Bool = true,
    type: String = "Type",
    name: String? = nil,
    block: String = "provide",
    scope: String = "transient",
    parameters: [Parameter] = .default
  ) -> Self {
    .init(
      id: .init(""),
      module: module,
      isFunc: isFunc,
      type: type,
      name: name,
      block: block,
      scope: scope,
      parameters: parameters)
  }
}

extension Array where Element == DependencyUiModel.Parameter {
  static let `default`: [Element] = [
    .init(type: "B", label: nil, id: nil, isLast: false),
    .init(type: "A", label: "a", id: nil, isLast: false),
    .init(type: "C", label: "c", id: "cType", isLast: true),
  ]
}
